<template><div v-if="server" class="max-w-4xl mx-auto p-5 sm:p-8"><h1 class="text-2xl font-bold text-white">General settings</h1><p class="text-dark-400 text-sm mt-1">แก้ไขได้เมื่อเซิร์ฟเวอร์หยุด ค่าใหม่จะถูกใช้ในการเริ่มครั้งถัดไป</p><form class="mt-6 space-y-5" @submit.prevent="save"><fieldset :disabled="!editable" class="space-y-5 disabled:opacity-50"><section class="panel"><h2>General</h2><div class="grid sm:grid-cols-2 gap-4 mt-4"><label class="field sm:col-span-2">Server name<input v-model="form.name" maxlength="80" required /></label><label class="field sm:col-span-2">Message of the day<input v-model="form.motd" maxlength="120" /></label><label class="field">Max players<input v-model.number="form.max_players" type="number" min="1" max="1000" required /></label><label class="field">Server port<input v-model.number="form.port" type="number" min="1" max="65535" required /><small>ต้องไม่ซ้ำกับเซิร์ฟเวอร์อื่น</small></label></div></section><section class="panel"><h2>World & gameplay</h2><div class="grid sm:grid-cols-2 gap-4 mt-4"><label class="field">World seed<input v-model="form.world_seed" placeholder="ปล่อยว่างเพื่อสุ่ม" /></label><label class="field">World type<select v-model="form.world_type"><option value="normal">Normal</option><option value="flat">Flat</option><option value="largeBiomes">Large biomes</option><option value="amplified">Amplified</option><option value="single_biome_surface">Single biome surface</option></select></label><label class="field">Difficulty<select v-model="form.difficulty"><option value="peaceful">Peaceful</option><option value="easy">Easy</option><option value="normal">Normal</option><option value="hard">Hard</option></select></label><label class="field">Gamemode<select v-model="form.gamemode"><option value="survival">Survival</option><option value="creative">Creative</option><option value="adventure">Adventure</option><option value="spectator">Spectator</option></select></label><label class="field">View distance<input v-model.number="form.view_distance" type="number" min="2" max="32" /><small>2–32 chunks</small></label><label class="field">Simulation distance<input v-model.number="form.simulation_distance" type="number" min="2" max="32" /><small>2–32 chunks</small></label><label class="check"><input v-model="form.pvp" type="checkbox" /> เปิด PVP</label></div></section><section class="panel"><h2>Network & player safety</h2><div class="grid sm:grid-cols-2 gap-4 mt-4"><label class="field">Player idle timeout (วินาที)<input v-model.number="form.player_idle_timeout" type="number" min="0" /><small>0 = ปิดการตัดการเชื่อมต่ออัตโนมัติ</small></label><div class="space-y-3 pt-5"><label class="check"><input v-model="form.online_mode" type="checkbox" /> Online mode (ตรวจสอบบัญชีแท้)</label><label class="check"><input v-model="form.prevent_proxy_connections" type="checkbox" /> Prevent proxy connections</label></div></div></section><section class="panel"><h2>Operators & additional permissions</h2><div class="grid sm:grid-cols-2 gap-4 mt-4"><label class="field sm:col-span-2">Server OP<input v-model="form.op_names" placeholder="tomson,tomson2" /><small>คั่นชื่อผู้เล่นด้วย comma</small></label><label class="field">OP permission level<select v-model.number="form.op_permission_level"><option :value="1">1 — bypass spawn protection</option><option :value="2">2 — use commands</option><option :value="3">3 — moderation commands</option><option :value="4">4 — full permissions</option></select></label><div class="space-y-3 pt-5"><label class="check"><input v-model="form.enable_command_blocks" type="checkbox" /> Enable command blocks</label><label class="check"><input v-model="form.allow_flight" type="checkbox" /> Allow flight</label><label class="check"><input v-model="form.whitelist" type="checkbox" /> Enable whitelist</label></div></div></section></fieldset><p v-if="error" class="text-red-300 text-sm">{{error}}</p><button v-if="editable" class="button primary" :disabled="saving">{{saving?'กำลังบันทึก…':'บันทึกการตั้งค่า'}}</button></form><hr class="border-dark-700 my-8"/><section><h2 class="text-red-300 font-semibold">ลบเซิร์ฟเวอร์</h2><p class="text-dark-500 text-sm mt-1">ระบบจะหยุดเซิร์ฟเวอร์ (ถ้ากำลังทำงาน) แล้วลบข้อมูลทั้งหมดถาวร</p><button class="button danger mt-4" @click="confirmDelete=true">ลบเซิร์ฟเวอร์</button></section><ConfirmDialog v-model="confirmDelete" danger title="ลบเซิร์ฟเวอร์?" message="ระบบจะหยุดและลบ container, world, mods และไฟล์ทั้งหมดถาวร" confirm-text="ลบถาวร" @confirm="remove" /></div></template>
<script setup lang="ts">definePageMeta({layout:'server'});const route=useRoute(),router=useRouter(),store=useServersStore(),id=route.params.id as string;const server=computed(()=>store.servers.find(s=>s.id===id));const form=reactive<any>({}),saving=ref(false),error=ref(''),confirmDelete=ref(false);const editable=computed(()=>server.value?.status==='stopped');function assign(){if(server.value)Object.assign(form,server.value,{whitelist:!!server.value.whitelist,online_mode:!!server.value.online_mode,pvp:!!server.value.pvp,enable_command_blocks:!!server.value.enable_command_blocks,prevent_proxy_connections:!!server.value.prevent_proxy_connections,allow_flight:!!server.value.allow_flight})}async function save(){saving.value=true;error.value='';try{await store.updateServer(id,form)}catch(e:any){error.value=e?.data?.statusMessage||'บันทึกไม่สำเร็จ'}finally{saving.value=false}}async function remove(){try{await store.deleteServer(id);router.push('/')}catch(e:any){error.value=e?.data?.statusMessage||'ลบไม่สำเร็จ'}}onMounted(async()=>{await store.fetchServer(id);assign()})</script><style scoped>.panel{@apply rounded-2xl bg-dark-900 border border-dark-700 p-5}.panel h2{@apply text-white font-semibold}.field{@apply flex flex-col gap-1.5 text-sm text-dark-300}.field input,.field select{@apply rounded-lg bg-dark-800 border border-dark-600 px-3 py-2.5 text-white outline-none focus:border-mc-green}.field small{@apply text-xs text-dark-500}.check{@apply flex gap-2 items-center text-sm text-dark-300}.check input{@apply accent-green-400}.button{@apply rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50}.primary{@apply bg-mc-green hover:bg-green-300 text-dark-950}.danger{@apply bg-red-700 hover:bg-red-600 text-white}</style>
